<section class="module-hero"><div><span class="module-kicker"><?= htmlspecialchars($ticket['reference']) ?></span><h1><?= htmlspecialchars($ticket['subject']) ?></h1><p>Statut : <?= htmlspecialchars($ticket['status']) ?> · Priorité : <?= htmlspecialchars($ticket['priority']) ?></p></div><a class="btn secondary" href="/academie/tickets">← Mes tickets</a></section>
<section class="module-panel"><div class="ticket-thread"><?php foreach($messages as $m): ?><div class="ticket-message <?= $m['sender_role']==='staff'?'staff':'' ?>"><strong><?= htmlspecialchars($m['sender_role']==='staff'?'Équipe IFMAP':($m['name']??'Vous')) ?></strong><div><?= nl2br(htmlspecialchars($m['message'])) ?></div><small><?= htmlspecialchars($m['created_at']) ?></small></div><?php endforeach ?></div></section>
<?php if($ticket['status']!=='closed'): ?><section class="module-panel"><form class="module-form" method="post" action="/academie/ticket/repondre"><input type="hidden" name="ticket_id" value="<?= (int)$ticket['id'] ?>"><label>Ajouter un message<textarea name="message" required></textarea></label><button class="btn primary">Envoyer</button></form></section><?php endif ?>
